/* ---------- drawing helpers for this lesson (prefixed ZS_ so they never clash with engine globals) ---------- */
const ZS_F='font-family="Nunito Sans, sans-serif"';
const ZS_T=(x,y,t,o={})=>`<text x="${x}" y="${y}" ${ZS_F} font-size="${o.fs||24}" font-weight="${o.fw||600}" text-anchor="${o.a||'start'}" fill="${o.fill||'#18213A'}">${t}</text>`;
const ZS_L=(x1,y1,x2,y2,col='#5C6577',w=2,ex='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" ${ex}/>`;
const ZS_box=(x,y,w,h,o={})=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${o.r??14}" fill="${o.fill||'#FFFFFF'}" stroke="${o.st||'#CED4DA'}" stroke-width="${o.sw||2}"/>`;
const ZS_curve=(f,t0,t1,x0,x1,yc,k,col,w=4,n=120,ex='')=>{let p=[];for(let i=0;i<=n;i++){const t=t0+(t1-t0)*i/n;p.push(`${(x0+(x1-x0)*i/n).toFixed(1)},${(yc-k*f(t)).toFixed(1)}`)}return `<polyline points="${p.join(' ')}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round" ${ex}/>`};
/* stems of computed values v[i] at x = x0 + i*dx, baseline yc, k px per unit (negative values hang down) */
const ZS_stems=(v,x0,dx,yc,k,col,r=7,w=4)=>v.map((q,i)=>{const x=x0+i*dx,y=yc-k*q;return ZS_L(x,yc,x,y.toFixed(1),col,w)+`<circle cx="${x}" cy="${y.toFixed(1)}" r="${r}" fill="${col}"/>`}).join('');
const ZS_arrow=(x1,y1,x2,y2,col='#18213A',w=3)=>{const a=Math.atan2(y2-y1,x2-x1),h=14;return ZS_L(x1,y1,x2-h*.6*Math.cos(a),y2-h*.6*Math.sin(a),col,w)+`<polygon points="${x2},${y2} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`};
const ZS_X=(x,y,s,col,w=5)=>ZS_L(x-s,y-s,x+s,y+s,col,w)+ZS_L(x-s,y+s,x+s,y-s,col,w);          // a pole
const ZS_O=(x,y,r,col)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="#FFFFFF" stroke="${col}" stroke-width="4"/>`;  // a zero
const ZS_axes=(cx,cy,R,lab=true)=>ZS_L(cx-R-24,cy,cx+R+40,cy,'#ADB5BD',2)+ZS_L(cx,cy+R+24,cx,cy-R-24,'#ADB5BD',2)+(lab?ZS_T(cx+R+40,cy-10,'Re z',{fs:20,a:'end',fill:'#5C6577'})+ZS_T(cx+8,cy-R-8,'Im z',{fs:20,fill:'#5C6577'}):'');
const ZS_circ=(cx,cy,r,col,w=3,ex='')=>`<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="${col}" stroke-width="${w}" ${ex}/>`;
/* shaded ring r1 < |z| < r2 (r2 = 0 means everything outside r1 inside the square of half-side H) */
const ZS_ring=(cx,cy,r1,r2,col,op=.16,H=0)=>{const hole=r1>0?`M${cx+r1},${cy} A${r1},${r1} 0 1 0 ${cx-r1},${cy} A${r1},${r1} 0 1 0 ${cx+r1},${cy} Z`:'';
 const out=r2>0?`M${cx+r2},${cy} A${r2},${r2} 0 1 0 ${cx-r2},${cy} A${r2},${r2} 0 1 0 ${cx+r2},${cy} Z`:`M${cx-H},${cy-H} H${cx+H} V${cy+H} H${cx-H} Z`;
 return `<path d="${out} ${hole}" fill="${col}" fill-opacity="${op}" fill-rule="evenodd"/>`};
/* computed sequences */
const ZS_half=n=>Math.pow(0.5,n);
const ZS_nhalf=[0,1,2,3,4,5,6,7].map(n=>n*Math.pow(0.5,n));              // 0, 0.5, 0.5, 0.375, 0.25 ...
const ZS_step=[0,1,2,3,4,5,6,7].map(n=>2-Math.pow(0.5,n));                // 1, 1.5, 1.75, 1.875 ... -> 2
const ZS_gain=(a,w)=>1/Math.sqrt(1+a*a-2*a*Math.cos(w));                  // |H(e^jw)| for H = 1/(1 - a z^-1)
const ZS_xw=n=>n<0?-(4/3)*Math.pow(2,n):-(1/3)*Math.pow(0.5,n);           // worked example: the two-sided answer
const ZS_xu=n=>-(1/3)*Math.pow(0.5,n)+(4/3)*Math.pow(2,n);                 // the u[n]-on-every-term mistake

